fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // Requires: The input list must not be empty and k must be a valid index.
    // Ensures: The returned vector contains all elements of the original list except the k-th element.
    // The length of the returned vector is one less than the input list.
    // The elements in the returned vector maintain the order of the original list.
    // 
    // Requires: 
    //     list.len() > 0
    //     k < list.len() + 1
    // Ensures:
    //     result.len() == list.len() - 1
    //     forall(i: usize | 0 <= i < result.len() ==> result[i] == list[i + (if i >= k - 1 { 1 } else { 0 })])
    //     result == list[0..k-1].to_vec() + list[k..].to_vec()
    
    let mut new_list = Vec::with_capacity(list.len() - 1);
    
    // Invariant: At the start of each iteration, new_list contains all elements of list
    // except for the k-th element (0-based index).
    // Decreases: list.len() - i
    for (i, &value) in list.iter().enumerate() {
        // Skip the element at position k-1 (0-based index)
        if i != k - 1 {
            new_list.push(value);
        }
    }
    
    new_list
}